INSERT INTO fund_report_vector (fund_code, manager_name, report_quarter, section_title, content) VALUES ('005827', '张坤', '2024Q2', '投资策略与运作分析', '在报告期内，本基金维持了对商业模式优秀、具备极强自由现金流产生能力与高资本回报率企业的核心配置。我们深信，时间是优秀企业的朋友，在消费和互联网优质资产估值深度回调后，龙头企业的股东回报率、分红与回购力度显著提升，具备强劲的长期复利价值。');
INSERT INTO fund_report_vector (fund_code, manager_name, report_quarter, section_title, content) VALUES ('161005', '朱少醒', '2024Q2', '投资策略与运作分析', '本基金在二季度依然保持了较高的股票仓位。我们坚持自下而上精选具有良好企业基因、优秀管理层以及估值处于合理或低估区间的成长标的。在行业配置上重视分散均衡，重点布局具备长期竞争壁垒的先进制造、高端装备和消费龙头。');
INSERT INTO fund_report_vector (fund_code, manager_name, report_quarter, section_title, content) VALUES ('003095', '葛兰', '2024Q2', '投资策略与运作分析', '从行业长期基本面来看，我国医药生物行业的创新升级与老龄化刚性需求依然具备长期确定性。二季度我们保持了创新药、医疗器械与CXO龙头的配置，重点聚焦具备全球化商业化潜力与真创新的优质企业。');
INSERT INTO fund_report_vector (fund_code, manager_name, report_quarter, section_title, content) VALUES ('163406', '谢治宇', '2024Q2', '投资策略与运作分析', '报告期内组合保持了较为均衡的行业配置结构，在半导体芯片、人工智能算力硬件、汽车智能化以及消费电子等科技制造方向进行了适度增配，同时兼顾低估值高股息资产的安全垫，力求在不确定性市场中获取长期阿尔法。');
INSERT INTO fund_report_vector (fund_code, manager_name, report_quarter, section_title, content) VALUES ('260108', '刘彦春', '2024Q2', '投资策略与运作分析', '逆周期宏观政策正逐步显现效果。中国经济正迈向高质量发展阶段，消费升级与品牌壁垒依然是极具吸引力的长跑赛道。我们在白酒、医疗服务、高端生活消费等领域继续重仓具备强大定价权的龙头企业。');
INSERT INTO fund_report_vector (fund_code, manager_name, report_quarter, section_title, content) VALUES ('320007', '刘慧影', '2024Q2', '投资策略与运作分析', '半导体产业周期迎来温和复苏，自主可控与前沿算力芯片需求呈现爆发式增长。本基金重点聚焦晶圆制造、先进封装与设备材料龙头企业，坚信科技创新是驱动中国经济中长期成长的核心引擎。');
